import type { IoniconName } from '../theme/icons';
import type { RichHealthEducation } from './healthEducationRichContent';

const img = (id: string) =>
  `https://images.unsplash.com/photo-${id}?w=900&q=85&auto=format&fit=crop`;

const HERO = {
  heart: img('1576091160399-112ba8d25d1d'),
  food: img('1490645935967-10de6ba17061'),
  sleep: img('1541783245831-57d6fb0926d3'),
  calm: img('1544367567-0f2fcb009e0b'),
  walk: img('1476480862126-209bfaa8edc8'),
  water: img('1548839140-29a749e1cf4d'),
  plants: img('1512621776951-a57141f2eefd'),
  strength: img('1517836357463-d25dfeac3438'),
  desk: img('1484480974693-6ca0a78fb36b'),
  bowl: img('1546069901-ba9599a7e63c'),
} as const;

type Hero = keyof typeof HERO;

type Card = { title: string; body: string };

type DeepTopic = {
  intro: string;
  takeaways: string[];
  learn: Card[];
  weekly: Card[];
  food: string;
  move: string;
  check: string;
  hero: Hero;
  related: string[];
};

const LEARN_ICONS: IoniconName[] = [
  'book-outline',
  'alert-circle-outline',
  'bulb-outline',
  'medkit-outline',
];

const WEEK_ICONS: IoniconName[] = [
  'calendar-outline',
  'checkmark-circle-outline',
  'flag-outline',
];

function page(topic: DeepTopic, accent: string, icon: IoniconName): RichHealthEducation {
  return {
    heroImageUrl: HERO[topic.hero],
    heroIcon: icon,
    accentColor: accent,
    intro: topic.intro,
    keyTakeaways: topic.takeaways,
    sections: [
      {
        title: 'What to understand',
        cards: topic.learn.map((card, i) => ({
          icon: LEARN_ICONS[i % LEARN_ICONS.length],
          title: card.title,
          body: card.body,
        })),
      },
      {
        title: 'Try this week',
        cards: topic.weekly.map((card, i) => ({
          icon: WEEK_ICONS[i % WEEK_ICONS.length],
          title: card.title,
          body: card.body,
        })),
      },
      {
        title: 'Food and movement',
        cards: [
          { icon: 'nutrition-outline', title: 'Eating', body: topic.food },
          { icon: 'walk-outline', title: 'Moving', body: topic.move },
        ],
      },
    ],
    tips: [{ title: 'When to get checked', body: topic.check }],
    relatedModuleIds: topic.related,
  };
}

function t(
  intro: string,
  takeaways: string[],
  learn: Card[],
  weekly: Card[],
  food: string,
  move: string,
  check: string,
  hero: Hero,
  related: string[],
): DeepTopic {
  return { intro, takeaways, learn, weekly, food, move, check, hero, related };
}

