export function getDeepHealthEducation(
  topicId: string,
  accent: string,
  icon: IoniconName,
): RichHealthEducation | null {
  const topic = DEEP_HEALTH_TOPICS[topicId];
  if (!topic) return null;
  return page(topic, accent, icon);
}
